        by_hw[hw] = []
    by_hw[hw].append(e)
for hw, entries in by_hw.items():
    print(f'=== {hw} ({len(entries)} entries) ===')
    for e in entries[:3]:  # max 3 per headword
        print(f'  id={e[\"entry_id\"]} | src={e[\"dict_source_type\"]} | dict={e.get(\"dict_name_ar\",\"\")} | root={e.get(\"root\",\"\")}')
        defn = (e.get('definitions_text','') or '')[:200]
        if defn: print(f'    def: {defn}')
        tr = e.get('translation_en','')
        if tr: print(f'    en: {tr}')
    if len(entries) > 3:
        print(f'  ... +{len(entries)-3} more')
    print()
"
